exercises.starter:
def factorial(n):
    # base case, then recurse toward it
    pass

exercises.solution:
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

exercises.starter:
def sum_to(n):
    # base case at 0, then add n to the sum of everything below it
    pass

exercises.solution:
def sum_to(n):
    if n <= 0:
        return 0
    return n + sum_to(n - 1)

exercises.starter:
def power(base, exp):
    # base case when exp is 0, then recurse on exp - 1
    pass

exercises.solution:
def power(base, exp):
    if exp == 0:
        return 1
    return base * power(base, exp - 1)

exercises.starter:
def sum_list(xs):
    # base case for the empty list, then first element plus the sum of the rest
    pass

exercises.solution:
def sum_list(xs):
    if not xs:
        return 0
    return xs[0] + sum_list(xs[1:])

exercises.starter:
def sum_nested(xs):
    # sum numbers, recursing into any element that is itself a list
    pass

exercises.solution:
def sum_nested(xs):
    if not xs:
        return 0
    first, rest = xs[0], xs[1:]
    head = sum_nested(first) if isinstance(first, list) else first
    return head + sum_nested(rest)
